module width_8to16(
    input clk, input rst_n, input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);
    reg [7:0] data_lock;
    reg flag;
    // data_out register is updated on the positive edge of the clock signal (posedge clk) or the negative edge of the reset signal (negedge rst_n).
    always @(posedge clk or negedge rst_n) begin
        // Reset condition: When the reset signal is active (negedge rst_n), the data_out register is cleared to 0.
        if (!rst_n)
            data_out <= 16'd0;
        // Width conversion condition: If the input data is valid (valid_in) and the flag signal is active, the data_out register is updated by concatenating the contents of the data_lock register (8 bits) and the data_in register (8 bits) to form a 16-bit output.
        else if (valid_in & flag)
            data_out <= {data_lock, data_in};
    end
    // data_lock register is updated on the positive edge of the clock signal (posedge clk) or the negative edge of the reset signal (negedge rst_n).
    always @(posedge clk or negedge rst_n) begin
        // Reset condition: When the reset signal is active (negedge rst_n), the data_lock register is cleared to 0.
        if (!rst_n)
            data_lock <= 8'd0;
        // Width conversion condition: If the input data is valid (valid_in) and the flag signal is inactive, the data_lock register is updated with the input data.
        else if (valid_in & !flag)
            data_lock <= data_in;
    end
    // flag register is updated on the positive edge of the clock signal (posedge clk) or the negative edge of the reset signal (negedge rst_n).
    always @(posedge clk or negedge rst_n) begin
        // Reset condition: When the reset signal is active (negedge rst_n), the flag register is cleared to 0.
        if (!rst_n)
            flag <= 1'b0;
        // Width conversion condition: If the input data is valid (valid_in) and the flag signal is inactive, the flag register is set to 1.
        else if (valid_in & !flag)
            flag <= 1'b1;
        // Reset flag condition: If the input data is valid (valid_in) and the flag signal is active, the flag register is cleared to 0.
        else if (valid_in & flag)
            flag <= 1'b0;
    end
    // valid_out register is updated on the positive edge of the clock signal (posedge clk) or the negative edge of the reset signal (negedge rst_n).
    always @(posedge clk or negedge rst_n) begin
        // Reset condition: When the reset signal is active (negedge rst_n), the valid_out register is cleared to 0.
        if (!rst_n)
            valid_out <= 1'b0;
        // Output valid condition: If the input data is valid (valid_in) and the flag signal is active, the valid_out register is set to 1.
        else if (valid_in & flag)
            valid_out <= 1'b1;
        // Reset valid condition: If the input data is valid (valid_in) and the flag signal is inactive, the valid_out register is cleared to 0.
        else if (valid_in & !flag)
            valid_out <= 1'b0;
    end
endmodule
